begin;
create temp table game_friend_test_users(code text,id uuid,handle text);
insert into game_friend_test_users select code,gen_random_uuid(),'gf_'||code||'_'||substr(md5(random()::text),1,8) from (values('a'),('b'),('c')) x(code);
insert into auth.users(id,email,raw_user_meta_data) select id,handle||'@example.invalid',jsonb_build_object('display_name',code) from game_friend_test_users;
insert into public.profiles(id,handle,display_name) select id,handle,code from game_friend_test_users on conflict(id) do update set handle=excluded.handle;
update public.profiles set share_deck_stats=true where id in(select id from game_friend_test_users);
insert into public.friend_connections(requester_id,recipient_id,status,accepted_at) select a.id,b.id,'accepted',now() from game_friend_test_users a cross join game_friend_test_users b where a.code='a' and b.code='b';
create temp table game_friend_test_decks(code text,id uuid,owner_id uuid);
insert into game_friend_test_decks select x.code,gen_random_uuid(),u.id from (values('own','a'),('played','b'),('unplayed','b'),('archived','b'),('stranger','c')) x(code,owner) join game_friend_test_users u on u.code=x.owner;
insert into public.decks(id,owner_id,name,commander,decklist,archived_at) select id,owner_id,code,'Original Commander','',case when code='archived' then now() end from game_friend_test_decks;
insert into public.personal_games(deck_id,owner_id,won) select id,owner_id,true from game_friend_test_decks where code in('played','archived','stranger');
do $$
declare own uuid; friend uuid; outsider uuid; linked_deck uuid; own_deck uuid; game uuid; snapshot jsonb; saved jsonb; handle text;
begin
 select id into own from game_friend_test_users where code='a';select id,game_friend_test_users.handle into friend,handle from game_friend_test_users where code='b';select id into outsider from game_friend_test_users where code='c';
 select id into linked_deck from game_friend_test_decks where code='played';select id into own_deck from game_friend_test_decks where code='own';
 perform set_config('request.jwt.claim.sub',own::text,true);
 if (select count(*) from public.list_game_friends())<>1 then raise exception 'Accepted-friends scope failed';end if;
 if (select count(*) from public.get_friend_game_decks(friend))<>1 then raise exception 'Active/played deck filter failed';end if;
 if exists(select 1 from public.get_friend_game_decks(outsider)) then raise exception 'Stranger deck leaked';end if;
 update public.profiles set share_deck_stats=false,public_full_stats=false where id=friend;
 if exists(select 1 from public.get_friend_game_decks(friend)) then raise exception 'Private decks leaked';end if;
 update public.profiles set share_deck_stats=true where id=friend;
 snapshot:=jsonb_build_array(jsonb_build_object('name','You','commander','Own Commander'),jsonb_build_object('name','@'||handle,'commander','Original Commander','friend_id',friend::text,'friend_deck_id',linked_deck::text,'extra','keep'));
 insert into public.personal_games(owner_id,deck_id,won,players,notes) values(own,own_deck,false,snapshot,'keep note') returning id into game;
 update public.decks set commander='Changed Commander' where id=linked_deck;
 if (select players->1->>'commander' from public.personal_games where id=game)<>'Original Commander' then raise exception 'Commander snapshot changed';end if;
 delete from public.decks where id=linked_deck;
 select players into saved from public.personal_games where id=game;
 if saved->1 ? 'friend_id' or saved->1 ? 'friend_deck_id' then raise exception 'Deleted deck link remains';end if;
 if saved->1->>'commander'<>'Original Commander' or saved->1->>'name'<>'@'||handle or saved->1->>'extra'<>'keep' then raise exception 'Snapshot lost after friend deck deletion';end if;
 if (select count(*) from public.personal_games where owner_id=own)<>1 then raise exception 'Other player game deleted';end if;
 update public.personal_games set players=jsonb_set(players,'{1,friend_id}',to_jsonb(friend::text)) where id=game;
 perform public.friend_action(handle,'remove');
 select players into saved from public.personal_games where id=game;
 if saved->1 ? 'friend_id' or saved->1->>'commander'<>'Original Commander' then raise exception 'Unfriend cleanup failed';end if;
 update public.personal_games set players=snapshot where id=game;
 if (select players->1 ? 'friend_id' from public.personal_games where id=game) then raise exception 'Stale links accepted at save';end if;
 update public.personal_games set players=jsonb_build_array(jsonb_build_object('name','Manual player','commander','Manual Commander','friend_id','invalid-id')) where id=game;
 if (select players->0 ? 'friend_id' from public.personal_games where id=game) then raise exception 'Malformed link retained';end if;
 if has_function_privilege('authenticated','public.normalize_game_friend_links(uuid,jsonb)','EXECUTE') or has_function_privilege('anon','public.get_friend_game_decks(uuid)','EXECUTE') then raise exception 'Invalid API grants';end if;
 raise notice 'PASS friends/deck privacy, active played eligibility, snapshots, deck deletion, unfriend, stale/malformed saves and permissions';
end $$;
rollback;
